import{c as a,J as r,h as o,k as s}from"./chunks/framework.WgZQdPFo.js";const h=JSON.parse('{"title":"Аналитика и валютная корзина","description":"Глубокая аналитика благосостояния мастера, динамика Net Worth, валютная корзина и распределение капитала по классам активов.","frontmatter":{"title":"Аналитика и валютная корзина","description":"Глубокая аналитика благосостояния мастера, динамика Net Worth, валютная корзина и распределение капитала по классам активов.","order":22},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/analytics.md","filePath":"ru/docs/spaces/moy-kapital/analytics.md"}'),e={name:"ru/docs/spaces/moy-kapital/analytics.md"};function l(n,t,i,c,p,d){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="аналитика-и-валютная-корзина" tabindex="-1">Аналитика и валютная корзина <a class="header-anchor" href="#аналитика-и-валютная-корзина" aria-label="Permalink to &quot;Аналитика и валютная корзина&quot;">​</a></h1><p>Вкладка <strong>«Аналитика капитала»</strong> и панель <strong>«Статистика»</strong> предоставляют мастеру стратегический взгляд на развитие личных финансов. Здесь оценивается не сиюминутный остаток в кассе, а долгосрочный тренд: растет ли реальное благосостояние вашей семьи из года в год и насколько надежно капитал защищен от валютных и экономических штормов.</p><hr><h2 id="график-помесячнои-динамики-благосостояния" tabindex="-1">График помесячной динамики благосостояния <a class="header-anchor" href="#график-помесячнои-динамики-благосостояния" aria-label="Permalink to &quot;График помесячной динамики благосостояния&quot;">​</a></h2><p>Центральное место на экране занимает интерактивный многосерийный график, отображающий помесячную историю ключевых метрик:</p><ul><li>🟢 <strong>Совокупный капитал (Net Worth):</strong> генеральная линия вашего благосостояния.</li><li>🟣 <strong>Капитал производств:</strong> суммарная стоимость активов всех подключенных цехов (касса + сырье + продукция).</li><li>🔵 <strong>Чистая прибыль:</strong> операционный финансовый результат мастерских за вычетом прямых и накладных расходов.</li><li>🟡 <strong>Выручка:</strong> фактический объем поступивших оплат от клиентов.</li></ul><div class="info custom-block"><p class="custom-block-title">Сохранение истории удаленных мастерских</p><p>Если вы продали или закрыли одно из направлений и удалили рабочее пространство из программы, исторические снимки его капитала не стираются из графиков. ОмниКрафт ЕРП бережно консервирует помесячные слепки, чтобы график многолетней динамики благосостояния оставался непрерывным.</p></div><hr><h2 id="валютная-корзина-currency-basket" tabindex="-1">Валютная корзина (Currency Basket) <a class="header-anchor" href="#валютная-корзина-currency-basket" aria-label="Permalink to &quot;Валютная корзина (Currency Basket)&quot;">​</a></h2><p>Для защиты от девальваций и валютных колебаний программа строит интерактивный срез <strong>валютной корзины</strong>:</p><ul><li><strong>Многосегментный стек-бар (Stacked Bar):</strong> показывает процентное соотношение валют в общей массе ликвидных средств и инвестиций (например, $60%$ рубли, $25%$ доллары США, $15%$ стейблкоины USDT).</li><li><strong>Сводный список валют:</strong> детальная расшифровка по каждой валюте с указанием оригинальной суммы, эквивалента в базовой валюте и процентного веса.</li><li><strong>Названия валют по закону о языке:</strong> все валюты выводятся с корректными русскоязычными наименованиями (например, «Доллар США», «Евро», «Российский рубль») на основе стандарта Юникод (Babel).</li></ul><div class="tip custom-block"><p class="custom-block-title">Золотое правило диверсификации</p><p>Держите оперативную подушку цеха (на 2–3 месяца работы) в валюте основных поставщиков сырья, а инвестиционные излишки распределяйте между стабильными валютами и твердыми материальными активами.</p></div><hr><h2 id="панель-статистики-капитала" tabindex="-1">Панель статистики капитала <a class="header-anchor" href="#панель-статистики-капитала" aria-label="Permalink to &quot;Панель статистики капитала&quot;">​</a></h2><p>По кнопке <strong>«📊 Статистика»</strong> на верхней панели инструментов открывается специализированный аналитический виджет.</p><p>В зависимости от настроек программы он отображается в двух режимах:</p><ol><li><strong>Боковая выдвижная панель (Шторка):</strong> выезжает справа, не перекрывая основной экран, что удобно для одновременного просмотра списка счетов и структуры корзины.</li><li><strong>Модальное окно:</strong> центрированное диалоговое окно для сосредоточенного анализа цифр.</li></ol><p>Формат отображения виджета настраивается в диалоге <strong>«⚙️ Настройки пространства»</strong>.</p>',18)])])}const u=a(e,[["render",l]]);export{h as __pageData,u as default};
